INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q18469222', 'Portuguese campaigns of pacification and occupation', 'The Portuguese campaigns of pacification and occupation (Portuguese: Campanhas de pacificação e ocupação) were a vast set of military operations, conducted by the Portuguese Armed Forces in the overseas provinces of the Portuguese Empire, between 1838 and 1936. Action was seen at Chaimite, in Mozambique, where Mouzinho de Albuquerque captured the Vatua king Gungunhana but also at Môngua, in Angola.', 1880, NULL, NULL, 1920, NULL, NULL, 'decade', '1880s – 1920s', 30, 'https://en.wikipedia.org/wiki/Portuguese_campaigns_of_pacification_and_occupation'),
  ('Q609836', 'Portuguese Colonial War', 'The Portuguese Colonial War (Portuguese: Guerra Colonial Portuguesa), also known in Portugal as the Overseas War (Guerra do Ultramar) or in the former colonies as the War of Liberation (Guerra de Libertação), and also known as the Angolan, Guinea-Bissau and Mozambican Wars of Independence, was a 13-year-long conflict fought between Portugal''s military and the emerging nationalist movements in Portugal''s African colonies between 1961 and 1974. The Portuguese regime at the time, the Estado Novo, was overthrown by a military coup in 1974, and the change in government brought the conflict to an…', 1961, 2, 4, 1974, 4, 25, 'day', '4 February 1961 – 25 April 1974', 69, 'https://en.wikipedia.org/wiki/Portuguese_Colonial_War'),
  ('Q60750764', '1980 Guinea-Bissau coup d''état', 'The 1980 Guinea-Bissau coup d''état was a bloodless military coup that took place in Guinea-Bissau on 14 November 1980, led by Prime Minister General João Bernardo Vieira. It led to the deposition of President Luís Cabral (half-brother of anti-colonial leader Amílcar Cabral), who held the office since 1973, while the country''s War of Independence was still ongoing.', 1980, 11, 14, NULL, NULL, NULL, 'day', '14 November 1980', 39, 'https://en.wikipedia.org/wiki/1980_Guinea-Bissau_coup_d''%C3%A9tat'),
  ('Q1781457', 'Bissau-Guinean Civil War', 'The Guinea-Bissau Civil War was fought from 7 June 1998 to 10 May 1999 and was triggered by an attempted coup d''état against the government of President João Bernardo Vieira led by Brigadier-General Ansumane Mané. Government forces, backed by neighbouring states, clashed with the coup leaders who had quickly gained almost total control over the country''s armed forces.', 1998, 6, 7, 1999, 5, 10, 'day', '7 June 1998 – 10 May 1999', 57, 'https://en.wikipedia.org/wiki/Guinea-Bissau_Civil_War'),
  ('Q61946226', '2003 Guinea-Bissau coup d''état', 'The 2003 Guinea-Bissau coup d''état was the bloodless military coup that took place in Guinea-Bissau on 14 September 2003, led by General Veríssimo Correia Seabra against incumbent President Kumba Ialá. Seabra referred to the "incapacity" of Ialá''s government as justification for the takeover, together with a stagnant economy, political instability, and military discontent over unpaid salaries.', 2003, 9, 14, NULL, NULL, NULL, 'day', '14 September 2003', 37, 'https://en.wikipedia.org/wiki/2003_Guinea-Bissau_coup_d''%C3%A9tat'),
  ('Q4617394', '2010 Guinea-Bissau military unrest', 'The military unrest occurred in Guinea-Bissau on 1 April 2010. Prime Minister Carlos Gomes Junior was placed under house arrest by soldiers, who also detained Army Chief of Staff Zamora Induta.', 2010, NULL, NULL, NULL, NULL, NULL, 'year', '2010', 41, 'https://en.wikipedia.org/wiki/2010_Guinea-Bissau_military_unrest'),
  ('Q621827', '2012 Guinea-Bissau coup d''état', 'On 12 April 2012, a coup d''état in Guinea-Bissau was staged by elements of the armed forces about two weeks before the second round of a presidential election between Carlos Gomes Júnior and Kumba Ialá. The coup started in the evening with military personnel and equipment making its way onto the streets, followed by the state-owned media being taken off-air.', 2012, 4, 12, NULL, NULL, NULL, 'day', '12 April 2012', 50, 'https://en.wikipedia.org/wiki/2012_Guinea-Bissau_coup_d''%C3%A9tat'),
  ('Q137036104', '2025 Guinea-Bissau coup d''état', 'On 26 November 2025, the president of Guinea-Bissau, Umaro Sissoco Embaló, was arrested as part of a coup d''état carried out by Head of the Military Office of the Presidency Brigadier General Dinis Incanha. Military officers declared "total control" over the country and established the High Military Command for the Restoration of National Security and Public Order led by General Horta Inta-A Na Man.', 2025, 11, 26, NULL, NULL, NULL, 'day', '26 November 2025', 57, 'https://en.wikipedia.org/wiki/2025_Guinea-Bissau_coup_d''%C3%A9tat');

